};

'use client';

import {
    Anchor,
    Divider,
    Flex,
    Group,
    Image,
    Stack,
    Text,
    Title,
} from '@mantine/core';
import { type TableName } from 'prisma/zod/schemas';

import { AutoRefresh } from '@/components/AutoRefresh/AutoRefresh';
