import { RulesContent } from '@/components/RulesContent/RulesContent';

export const metadata = { title: 'Rules' };

const RulesPage = () => {
    return <RulesContent />;
};

export default RulesPage;

import { FamilyTreeIntro } from '@/components/FamilyTreeIntro/FamilyTreeIntro';
import playerService from '@/services/Player';

export const metadata = { title: 'Family Tree' };

/**
 * Server page that fetches the full player introduction hierarchy from the
 * Player service and passes it to {@link FamilyTreeIntro} for rendering.
 */
const FamilyTreePage = async () => {
    const tree = await playerService.getFamilyTree();

    return <FamilyTreeIntro data={tree} />;
};

export default FamilyTreePage;

import { TablesIntro } from '@/components/TablesIntro/TablesIntro';

export const metadata = { title: 'Tables' };

const TablesPage = () => {
    return <TablesIntro />;
};

export default TablesPage;

import { CountryMapIntro } from '@/components/CountryMapIntro/CountryMapIntro';
import countrySupporterService from '@/services/CountrySupporter';

export const metadata = { title: 'Country Map' };

/**
 * Server page that fetches all country-supporter relationships (with
 * country and player data) and passes them to {@link CountryMapIntro} for
 * rendering.
 */
const CountryMapPage = async () => {
    const countries =
        await countrySupporterService.getAllWithCountryAndPlayer();

    return <CountryMapIntro countries={countries} />;
};

export default CountryMapPage;

import { sendEnquiry } from '@/actions/sendEnquiry';
import { InfoContent } from '@/components/InfoContent/InfoContent';

export const metadata = { title: 'Info' };

const Page = () => {
    return <InfoContent onSendEnquiry={sendEnquiry} />;
};

export default Page;

import { notFound } from 'next/navigation';
import { TableNameSchema } from 'prisma/zod/schemas';

import { HomeContent } from '@/components/HomeContent/HomeContent';
import gameDayService from '@/services/GameDay';
import playerRecordService from '@/services/PlayerRecord';

const HomePage = async () => {
    const tables = [
        TableNameSchema.enum.points,
        TableNameSchema.enum.averages,
        TableNameSchema.enum.stalwart,
    ] as const;
    const year = await gameDayService.getCurrentYear();
    if (!year) return notFound();

    const tableRecords = await Promise.all(
        tables.map((table) =>
            playerRecordService.getTable(table, year, true, 3),
        ),
    );

    return (
        <HomeContent
            year={year}
            tables={tables}
            tableRecords={tableRecords}
        />
    );
};

export default HomePage;

