9	import { TitleWithYearDropdown } from '@/components/TitleWithYearDropdown/TitleWithYearDropdown';
10	import { getYearName } from '@/lib/tables';
11	import gameDayService from '@/services/GameDay';
12	import { FootyChannel } from '@/types/FootyChannel';
13	
14	interface PageProps {
15	    searchParams?: Promise<{
16	        year?: string;
17	    }>;
18	}
19	
20	/**
21	 * Asynchronously unpacks and validates search parameters for the footy games
22	 * page, fetching relevant data such as available years, the current game day,
23	 * and game statistics.
24	 *
25	 * - Validates the `year` parameter from the search params, ensuring it is a
26	 *   valid year present in the list of all years.
27	 * - If the year is invalid or missing, triggers a 404 not found response.
28	 * - Fetches the number of games played, cancelled, and remaining for the
29	 *   specified year.
30	 * - Ensures the canonical URL structure by redirecting if the current URL does
31	 *   not match the canonical format.
32	 * - Constructs a title and subhead string summarizing the games data.
33	 *
34	 * @param searchParams - The search parameters from the page props, expected to
35	 * include a `year` query parameter.
36	 * @returns An object containing the validated year, all available years, the
37	 * current game day, a title, and a subhead string.
38	 * @throws Redirects to the canonical URL if the current URL is not canonical.
39	 * @throws Triggers a 404 not found response if the year is invalid or not
40	 * present in the available years.
41	 */
42	const unpackParams = cache(async (searchParams: PageProps['searchParams']) => {
43	    const [resolvedSearchParams, allYears, currentGameDay] = await Promise.all([
44	        searchParams,
45	        gameDayService.getAllYears({
46	            includeAllTime: true,
47	            mostRecentFirst: true,
48	        }),
49	        gameDayService.getCurrent(),
50	    ]);
51	    const yearResult = z.coerce
52	        .number()
53	        .int()
54	        .min(0)
55	        .safeParse(resolvedSearchParams?.year ?? 0);
56	    const year = yearResult.success ? yearResult.data : undefined;
57	    if (year === undefined || !allYears.includes(year)) notFound();
58	
59	    const [gamesPlayed, gamesCancelled, gamesRemaining] = await Promise.all([
60	        gameDayService.getGamesPlayed(year, currentGameDay?.id),
61	        gameDayService.getGamesCancelled(year, currentGameDay?.id),
62	        gameDayService.getGamesRemaining(year),
63	    ]);
64	
65	    /* v8 ignore next -- year is always defined here; the notFound() guard above already excludes undefined */
66	    const canonicalSearch = year !== undefined ? `?year=${year}` : '';
67	    const canonicalUrl = `/footy/games/${canonicalSearch}`;
68	    const currentSearch =
69	        resolvedSearchParams?.year !== undefined
70	            ? `?year=${resolvedSearchParams.year}`
71	            : '';
72	    const currentUrl = `/footy/games/${currentSearch}`;
73	    if (currentUrl !== canonicalUrl) permanentRedirect(canonicalUrl);
74	
75	    const title = `${year ? `${year} ` : ''}Games`;
76	    const subheadValues = [];
77	    if (gamesPlayed) subheadValues.push(`${gamesPlayed} played`);
78	    if (gamesCancelled) subheadValues.push(`${gamesCancelled} cancelled`);
79	    if (gamesRemaining) subheadValues.push(`${gamesRemaining} confirmed`);
80	    const subhead = subheadValues.join(', ');
81	
82	    return { year, allYears, currentGameDay, title, subhead };
83	});
84	
85	/**
86	 * Generates metadata for the footy games page based on the provided search
87	 * parameters. Fetches the year from the search parameters and constructs a
88	 * title for the page using the year name. If the year is not provided or
89	 * invalid, it defaults to a generic title.
90	 * @param props - The page properties containing search parameters.
91	 * @returns A promise that resolves to a Metadata object with the generated
92	 * title.
93	 * @throws Redirects to the canonical URL if the current URL is not canonical.
94	 * @throws Triggers a 404 not found response if the year is invalid or not
95	 * present in the available years.
96	 */
97	export async function generateMetadata(props: PageProps): Promise<Metadata> {
98	    const { year } = await unpackParams(props.searchParams);
99	    return { title: `${getYearName(year)} Games` };
100	}
101	
102	/**
103	 * Server page component for displaying footy games. Fetches and validates the year from the search parameters, retrieves the list of game days for that year,
104	 * and renders a page with a title, subhead, and a list of game days. Also
105	 * includes an auto-refresh component that listens to relevant channels for
106	 * updates.
107	 * @param props - The page properties containing search parameters.
108	 * @returns A React element representing the games page.
109	 * @throws Redirects to the canonical URL if the current URL is not canonical.
110	 * @throws Triggers a 404 not found response if the year is invalid or not
111	 * present in the available years.
112	 * @remarks The page includes an auto-refresh mechanism that listens to the
113	 * "Games" and "Results" channels for real-time updates, ensuring that the
114	 * displayed data remains current without requiring manual refreshes.
115	 */
116	const GamesPage = async (props: PageProps) => {
117	    const { year, allYears, subhead } = await unpackParams(props.searchParams);
118	    const gameDays = await gameDayService.getAll({ year });
119	
120	    return (
121	        <Flex
122	            direction="column"
123	            align="center"
124	            gap="lg"
125	        >
126	            <AutoRefresh
127	                channels={[FootyChannel.Games, FootyChannel.Results]}
128	            />
129	            <Group
130	                justify="center"
131	                w="100%"
132	            >
133	                <TitleWithYearDropdown
134	                    order={1}
135	                    title="Games: "
136	                    year={year}
137	                    validYears={allYears}
138	                />
139	            </Group>
140	            <Title
141	                order={2}
142	                mb="xl"
143	            >
144	                {subhead}
145	            </Title>
146	            <GameDayList
147	                gameDays={gameDays}
148	                year={year}
149	            />
150	        </Flex>
151	    );
152	};
153	
154	export default GamesPage;
