24	/**
25	 * Unpacks and validates page parameters and search parameters for the footy
26	 * table page.
27	 *
28	 * This function validates the table name parameter against the TableNameSchema,
29	 * validates the year search parameter, and ensures the year exists in the
30	 * available years. It also handles canonical URL redirects to ensure consistent
31	 * URL formatting.
32	 *
33	 * @param params - The page route parameters containing the table name
34	 * @param searchParams - The URL search parameters, optionally containing a year
35	 * @returns A promise resolving to an object containing the validated table
36	 * name, year, and all available years
37	 * @throws {notFound} When the table parameter is invalid, year is invalid, or
38	 * year is not in the available years list
39	 * @throws {permanentRedirect} When the current URL doesn't match the canonical
40	 * URL format
41	 *
42	 * @example
43	 * ```tsx
44	 * const { table, year, allYears } = await unpackParams(params, searchParams);
45	 * ```
46	 */
47	const unpackParams = cache(
48	    async (
49	        params: PageProps['params'],
50	        searchParams: PageProps['searchParams'],
51	    ) => {
52	        const { table: tableParam } = await params;
53	
54	        const tableResult = TableNameSchema.safeParse(tableParam);
55	        if (!tableResult.success) notFound();
56	        const table = tableResult.data;
57	
58	        const resolvedSearchParams = await searchParams;
59	        const allYears = await playerRecordService.getAllYears({
60	            completed: false,
61	            mostRecentFirst: true,
62	        });
63	        const yearResult = z.coerce
64	            .number()
65	            .int()
66	            .min(0)
67	            .safeParse(resolvedSearchParams?.year ?? 0);
68	        const year = yearResult.success ? yearResult.data : undefined;
69	        if (year === undefined || !allYears.includes(year)) notFound();
70	
71	        const canonicalSearch = year ? `?year=${year}` : '';
72	        const canonicalUrl = `/footy/table/${table}${canonicalSearch}`;
73	        const currentSearch = resolvedSearchParams?.year
74	            ? `?year=${resolvedSearchParams.year}`
75	            : '';
76	        const currentUrl = `/footy/table/${table}${currentSearch}`;
77	        if (currentUrl !== canonicalUrl) permanentRedirect(canonicalUrl);
78	
79	        return { table, year, allYears };
80	    },
81	);
82	
83	/**
84	 * Generates metadata for the table page.
85	 * @param props - The page properties containing params and searchParams
86	 * @param props.params - The route parameters
87	 * @param props.searchParams - The search query parameters
88	 * @returns A promise that resolves to the page metadata with the qualified
89	 * table name as title
90	 */
91	export async function generateMetadata(props: PageProps): Promise<Metadata> {
92	    const { table, year } = await unpackParams(
93	        props.params,
94	        props.searchParams,
95	    );
96	
97	    return {
98	        title: QualifiedTableName(table, year),
99	    };
100	}
