116	const TablePage = async (props: PageProps) => {
117	    const { table, year, allYears } = await unpackParams(
118	        props.params,
119	        props.searchParams,
120	    );
121	
122	    const [tableQualified, tableUnqualified] = await Promise.all([
123	        playerRecordService.getTable(table, year, true),
124	        playerRecordService.getTable(table, year, false),
125	    ]);
126	
127	    return (
128	        <Stack
129	            p="xl"
130	            align="center"
131	        >
132	            <AutoRefresh
133	                channels={[FootyChannel.Results, FootyChannel.Players]}
134	            />
135	            <Group
