32	                params.delete('year');
33	            } else {
34	                params.set('year', String(year));
35	            }
36	            const query = params.toString();
37	            return query ? `${pathname}?${query}` : pathname;
38	        },
39	        [pathname, searchParams],
40	    );
41	
42	    return (
43	        <Group
44	            justify="center"
45	            align="baseline"
46	            gap="xs"
47	            wrap="wrap"
48	        >
49	            <Title order={order}>{title}</Title>
50	
51	            <Menu
52	                shadow="md"
53	                styles={{ dropdown: { maxHeight: '60vh', overflowY: 'auto' } }}
54	            >
55	                <Menu.Target>
56	                    <UnstyledButton
57	                        style={{
