59	                            fontWeight: `var(--mantine-h${order as number}-font-weight)`,
60	                            lineHeight: `var(--mantine-h${order as number}-line-height)`,
61	                            color: 'var(--mantine-color-anchor)',
62	                            border: '1px solid var(--mantine-primary-color-3)',
63	                            borderRadius: 'var(--mantine-radius-sm)',
64	                            padding: '0 8px',
65	                            width: 'fit-content',
66	                        }}
67	                    >
68	                        <Group gap={4}>
69	                            {getYearName(year)}
70	                            <IconChevronDown size={14} />
71	                        </Group>
72	                    </UnstyledButton>
73	                </Menu.Target>
74	
75	                <Menu.Dropdown>
76	                    {validYears.map((r) => (
77	                        <Menu.Item
78	                            key={r}
79	                            leftSection={
80	                                r === year ? <IconCheck size={14} /> : null
81	                            }
82	                            onClick={() => router.push(createYearHref(r))}
83	                        >
84	                            {getYearName(r)}
85	                        </Menu.Item>
86	                    ))}
87	                </Menu.Dropdown>
88	            </Menu>
89	        </Group>
90	    );
91	}
