import { Metadata } from 'next';
import { notFound, permanentRedirect } from 'next/navigation';
import { cache } from 'react';
import z from 'zod';

import { GameDayList } from '@/components/GameDayList/GameDayList';
import { YearPageShell } from '@/components/YearPageShell/YearPageShell';
import { getYearName } from '@/lib/tables';
import gameDayService from '@/services/GameDay';
import { FootyChannel } from '@/types/FootyChannel';

interface PageProps {
    searchParams?: Promise<{
        year?: string;
    }>;
}

/**
 * Asynchronously unpacks and validates search parameters for the footy games
 * page, fetching relevant data such as available years, the current game day,
 * and game statistics.
 *
 * - Validates the `year` parameter from the search params, ensuring it is a
 *   valid year present in the list of all years.
 * - If the year is invalid or missing, triggers a 404 not found response.
 * - Fetches the number of games played, cancelled, and remaining for the
 *   specified year.
 * - Ensures the canonical URL structure by redirecting if the current URL does
 *   not match the canonical format.
 * - Constructs a title and subhead string summarizing the games data.
 *
 * @param searchParams - The search parameters from the page props, expected to
 * include a `year` query parameter.
 * @returns An object containing the validated year, all available years, the
 * current game day, a title, and a subhead string.
 * @throws Redirects to the canonical URL if the current URL is not canonical.
 * @throws Triggers a 404 not found response if the year is invalid or not
 * present in the available years.
 */
const unpackParams = cache(async (searchParams: PageProps['searchParams']) => {
    const [resolvedSearchParams, allYears, currentGameDay] = await Promise.all([
        searchParams,
        gameDayService.getAllYears({
            includeAllTime: true,
            mostRecentFirst: true,
        }),
        gameDayService.getCurrent(),
    ]);
    const yearResult = z.coerce
        .number()
        .int()
        .min(0)
        .safeParse(resolvedSearchParams?.year ?? 0);
    const year = yearResult.success ? yearResult.data : undefined;
    if (year === undefined || !allYears.includes(year)) notFound();

    const [gamesPlayed, gamesCancelled, gamesRemaining] = await Promise.all([
        gameDayService.getGamesPlayed(year, currentGameDay?.id),
        gameDayService.getGamesCancelled(year, currentGameDay?.id),
        gameDayService.getGamesRemaining(year),
    ]);

    /* v8 ignore next -- year is always defined here; the notFound() guard above already excludes undefined */
    const canonicalSearch = year !== undefined ? `?year=${year}` : '';
    const canonicalUrl = `/footy/games/${canonicalSearch}`;
    const currentSearch =
        resolvedSearchParams?.year !== undefined
            ? `?year=${resolvedSearchParams.year}`
            : '';
    const currentUrl = `/footy/games/${currentSearch}`;
    if (currentUrl !== canonicalUrl) permanentRedirect(canonicalUrl);

    const title = `${year ? `${year} ` : ''}Games`;
    const subheadValues = [];
    if (gamesPlayed) subheadValues.push(`${gamesPlayed} played`);
    if (gamesCancelled) subheadValues.push(`${gamesCancelled} cancelled`);
    if (gamesRemaining) subheadValues.push(`${gamesRemaining} confirmed`);
    const subhead = subheadValues.join(', ');

    return { year, allYears, currentGameDay, title, subhead };
});

/**
 * Generates metadata for the footy games page based on the provided search
 * parameters. Fetches the year from the search parameters and constructs a
 * title for the page using the year name. If the year is not provided or
 * invalid, it defaults to a generic title.
 * @param props - The page properties containing search parameters.
 * @returns A promise that resolves to a Metadata object with the generated
 * title.
 * @throws Redirects to the canonical URL if the current URL is not canonical.
 * @throws Triggers a 404 not found response if the year is invalid or not
 * present in the available years.
 */
export async function generateMetadata(props: PageProps): Promise<Metadata> {
    const { year } = await unpackParams(props.searchParams);
    return { title: `${getYearName(year)} Games` };
}

/**
 * Server page component for displaying footy games. Fetches and validates the year from the search parameters, retrieves the list of game days for that year,
 * and renders a page with a title, subhead, and a list of game days. Also
 * includes an auto-refresh component that listens to relevant channels for
 * updates.
 * @param props - The page properties containing search parameters.
 * @returns A React element representing the games page.
 * @throws Redirects to the canonical URL if the current URL is not canonical.
 * @throws Triggers a 404 not found response if the year is invalid or not
 * present in the available years.
 * @remarks The page includes an auto-refresh mechanism that listens to the
 * "Games" and "Results" channels for real-time updates, ensuring that the
 * displayed data remains current without requiring manual refreshes.
 */
const GamesPage = async (props: PageProps) => {
    const { year, allYears, subhead } = await unpackParams(props.searchParams);
    const gameDays = await gameDayService.getAll({ year });

    return (
        <YearPageShell
            title="Games: "
            year={year}
            validYears={allYears}
            autoRefreshChannels={[FootyChannel.Games, FootyChannel.Results]}
            align="center"
            gap="lg"
            subheading={subhead}
        >
            <GameDayList
                gameDays={gameDays}
                year={year}
            />
        </YearPageShell>
    );
};

export default GamesPage;

import { Metadata } from 'next';
import { notFound, permanentRedirect } from 'next/navigation';
import { TableNameSchema } from 'prisma/zod/schemas';
import { cache } from 'react';
import z from 'zod';

import { YearPageShell } from '@/components/YearPageShell/YearPageShell';
import { YearTable } from '@/components/YearTable/YearTable';
import { QualifiedTableName, TableTitle } from '@/lib/tables';
import playerRecordService from '@/services/PlayerRecord';
import { FootyChannel } from '@/types/FootyChannel';

interface PageProps {
    params: Promise<{
        table: string;
    }>;
    searchParams?: Promise<{
        year?: string;
    }>;
}

/**
 * Unpacks and validates page parameters and search parameters for the footy
 * table page.
 *
 * This function validates the table name parameter against the TableNameSchema,
 * validates the year search parameter, and ensures the year exists in the
 * available years. It also handles canonical URL redirects to ensure consistent
 * URL formatting.
 *
 * @param params - The page route parameters containing the table name
 * @param searchParams - The URL search parameters, optionally containing a year
 * @returns A promise resolving to an object containing the validated table
 * name, year, and all available years
 * @throws {notFound} When the table parameter is invalid, year is invalid, or
 * year is not in the available years list
 * @throws {permanentRedirect} When the current URL doesn't match the canonical
 * URL format
 *
 * @example
 * ```tsx
 * const { table, year, allYears } = await unpackParams(params, searchParams);
 * ```
 */
const unpackParams = cache(
    async (
        params: PageProps['params'],
        searchParams: PageProps['searchParams'],
    ) => {
        const { table: tableParam } = await params;

        const tableResult = TableNameSchema.safeParse(tableParam);
        if (!tableResult.success) notFound();
        const table = tableResult.data;

        const resolvedSearchParams = await searchParams;
        const allYears = await playerRecordService.getAllYears({
            completed: false,
            mostRecentFirst: true,
        });
        const yearResult = z.coerce
            .number()
            .int()
            .min(0)
            .safeParse(resolvedSearchParams?.year ?? 0);
        const year = yearResult.success ? yearResult.data : undefined;
        if (year === undefined || !allYears.includes(year)) notFound();

        const canonicalSearch = year ? `?year=${year}` : '';
        const canonicalUrl = `/footy/table/${table}${canonicalSearch}`;
        const currentSearch = resolvedSearchParams?.year
            ? `?year=${resolvedSearchParams.year}`
            : '';
        const currentUrl = `/footy/table/${table}${currentSearch}`;
        if (currentUrl !== canonicalUrl) permanentRedirect(canonicalUrl);

        return { table, year, allYears };
    },
);

/**
 * Generates metadata for the table page.
 * @param props - The page properties containing params and searchParams
 * @param props.params - The route parameters
 * @param props.searchParams - The search query parameters
 * @returns A promise that resolves to the page metadata with the qualified
 * table name as title
 */
export async function generateMetadata(props: PageProps): Promise<Metadata> {
    const { table, year } = await unpackParams(
        props.params,
        props.searchParams,
    );

    return {
        title: QualifiedTableName(table, year),
    };
}

/**
 * Renders the Footy table page for a specific table and year.
 *
 * This async server component:
 * - Resolves route and query parameters via `unpackParams`.
 * - Fetches both qualified and unqualified player records for the selected
 *   table/year.
 * - Displays a `TitleWithYearDropdown` and a `YearTable` populated with the
 *   retrieved data.
 *
 * @param props - Next.js page props containing dynamic route params and search
 * params.
 * @returns A React element with year selection controls and table results.
 */
const TablePage = async (props: PageProps) => {
    const { table, year, allYears } = await unpackParams(
        props.params,
        props.searchParams,
    );

    const [tableQualified, tableUnqualified] = await Promise.all([
        playerRecordService.getTable(table, year, true),
        playerRecordService.getTable(table, year, false),
    ]);

    return (
        <YearPageShell
            title={`${TableTitle(table)}: `}
            year={year}
            validYears={allYears}
            autoRefreshChannels={[FootyChannel.Results, FootyChannel.Players]}
            p="xl"
            align="center"
            groupMb="xl"
        >
            <YearTable
                table={table}
                year={year}
                qualified={tableQualified}
                unqualified={tableUnqualified}
            />
        </YearPageShell>
    );
};

export default TablePage;

