import clubSupporterService from '@/services/ClubSupporter';
import countrySupporterService from '@/services/CountrySupporter';
import outcomeService from '@/services/Outcome';
import playerService from '@/services/Player';
import playerExtraEmailService from '@/services/PlayerExtraEmail';

export const metadata = { title: 'Download My Data' };

const Page = async () => {
    const user = await getCurrentUser();
    const playerId = user?.playerId ?? 0;

    if (!playerId) {
        return (
            <StatusNotification
                icon={<IconX size={config.notificationIconSize} />}
                color="red"
                message="This account is not linked to a player profile yet."
            />
        );
    }

    const [player, extraEmails, countries, clubs, outcomes] = await Promise.all(
        [
            playerService.getById(playerId),
            playerExtraEmailService.getAll(playerId),
            countrySupporterService.getByPlayer(playerId),
            clubSupporterService.getByPlayer(playerId),
            outcomeService.getByPlayer(playerId),
        ],
    );

    if (!player) {
        return (
            <StatusNotification
                icon={<IconX size={config.notificationIconSize} />}
                color="red"
                message="Failed to load player data."
            />
        );
    }

    const gamesResponded = outcomes.filter(
        (outcome) => outcome.response !== null,
    );
    const gamesPlayed = outcomes.filter((outcome) => outcome.points !== null);
    const respondedGameDays = gamesResponded.map(
        (outcome) => outcome.gameDayId,
    );
    const playedGameDays = gamesPlayed.map((outcome) => outcome.gameDayId);
    const accountEmail =
        (player as { accountEmail?: string | null }).accountEmail ?? null;

    const totals = {
        accountEmail,
        firstResponded:
            respondedGameDays.length > 0
                ? Math.min(...respondedGameDays)
                : null,
        lastResponded:
            respondedGameDays.length > 0
                ? Math.max(...respondedGameDays)
                : null,
        firstPlayed:
            playedGameDays.length > 0 ? Math.min(...playedGameDays) : null,
        lastPlayed:
            playedGameDays.length > 0 ? Math.max(...playedGameDays) : null,
        gamesPlayed: gamesPlayed.length,
        gamesWon: gamesPlayed.filter((outcome) => outcome.points === 3).length,
        gamesDrawn: gamesPlayed.filter((outcome) => outcome.points === 1)
            .length,
        gamesLost: gamesPlayed.filter((outcome) => outcome.points === 0).length,
    };

    const payload: DownloadMyDataPayload = {
        meta: {
            exportedAt: new Date().toISOString(),
            playerId: playerId,
            userEmail: user?.email ?? null,
        },
        profile: player,
        extraEmails,
        countries,
        clubs,
        totals,
        outcomes,
    };

    const serialisedPayload = JSON.parse(
        JSON.stringify(payload),
    ) as DownloadMyDataPayload;

    return <DownloadMyData data={serialisedPayload} />;
};

export default Page;

import { IconX } from '@tabler/icons-react';

import { updatePlayer } from '@/actions/updatePlayer';
import { AutoRefresh } from '@/components/AutoRefresh/AutoRefresh';
import { PlayerProfileForm } from '@/components/PlayerProfileForm/PlayerProfileForm';
import { StatusNotification } from '@/components/StatusNotification/StatusNotification';
import { getCurrentUser } from '@/lib/auth.server';
import { config } from '@/lib/config';
import clubService from '@/services/Club';
import clubSupporterService from '@/services/ClubSupporter';
import countryService from '@/services/Country';
import countrySupporterService from '@/services/CountrySupporter';
import playerService from '@/services/Player';
import playerExtraEmailService from '@/services/PlayerExtraEmail';
import { FootyChannel } from '@/types/FootyChannel';

export const metadata = { title: 'Profile' };

const Page = async () => {
    const user = await getCurrentUser();
    const playerId = user?.playerId;

    if (!playerId) {
        return (
            <StatusNotification
                icon={<IconX size={config.notificationIconSize} />}
                color="red"
                message="This account is not linked to a player profile yet."
            />
        );
    }

    const [player, extraEmails, countries, clubs, allCountries, allClubs] =
        await Promise.all([
            playerService.getById(playerId),
            playerExtraEmailService.getAll(playerId),
            countrySupporterService.getByPlayer(playerId),
            clubSupporterService.getByPlayer(playerId),
            countryService.getAll(),
            clubService.getAll(),
        ]);

    if (!player) {
        return (
            <StatusNotification
                icon={<IconX size={config.notificationIconSize} />}
                color="red"
                message="Failed to load player profile."
            />
        );
    }

    return (
        <>
            <AutoRefresh channels={FootyChannel.Players} />
            <PlayerProfileForm
                player={player}
                accountEmail={user.email}
                extraEmails={extraEmails}
                countries={countries}
                clubs={clubs}
                allCountries={allCountries}
                allClubs={allClubs}
                onUpdatePlayer={updatePlayer}
            />
        </>
    );
};

export default Page;

import { listUsersAction, setAdminRoleAction } from '@/actions/auth';
import { AdminUserList } from '@/components/AdminUserList/AdminUserList';
import { AutoRefresh } from '@/components/AutoRefresh/AutoRefresh';
import { StatusNotification } from '@/components/StatusNotification/StatusNotification';
import { UserWithRolePayload } from '@/lib/core/auth';
import { toPublicMessage } from '@/lib/errors/AppError';
import { captureUnexpectedError } from '@/lib/observability/sentry';
import { FootyChannel } from '@/types/FootyChannel';

export const metadata = { title: 'Admin: Users' };

export default async function Page() {
    let users: UserWithRolePayload[] = [];

    try {
        users = await listUsersAction();
    } catch (error) {
        captureUnexpectedError(error, {
            layer: 'server',
            action: 'listUsersAction',
            component: 'AdminUserList',
            route: '/footy/admin/users',
        });
        return (
            <StatusNotification
                variant="plain"
                color="red"
                message={toPublicMessage(error, 'Failed to fetch users.')}
            />
        );
    }

    return (
        <>
            <AutoRefresh channels={FootyChannel.Users} />
            <AdminUserList
                users={users}
                setAdminRole={setAdminRoleAction}
            />
        </>
    );
}

import { submitGameInvitationResponse } from '@/actions/submitGameInvitationResponse';
import { GameInvitationResponseForm } from '@/components/GameInvitationResponseForm/GameInvitationResponseForm';
import { StatusNotification } from '@/components/StatusNotification/StatusNotification';
import { getGameInvitationResponseDetails } from '@/lib/gameInvitations';

interface PageProps {
    params: Promise<{ token: string }>;
}

export const metadata = { title: 'Response' };

const Page = async ({ params }: PageProps) => {
    const { token } = await params;
    const details = await getGameInvitationResponseDetails(token);

    if (!details) {
        return (
            <StatusNotification
                variant="plain"
                message="Invitation details are missing."
                anchor={{ href: '/footy/game', label: 'Go to the game page' }}
            />
        );
    }

    return (
        <GameInvitationResponseForm
            details={details}
            onSubmitGameInvitationResponse={submitGameInvitationResponse}
        />
    );
};

export default Page;

