import type { Mock } from 'vitest';
import { describe, expect, it, vi } from 'vitest';

vi.mock('@/actions/auth-export', () => ({
    authExport: vi.fn(),
}));

vi.mock('@/actions/getProgress', () => ({
    getProgress: vi.fn(),
}));

vi.mock('@/actions/updatePlayerRecords', () => ({
    updatePlayerRecords: vi.fn(),
}));

vi.mock('@/components/AdminDashboard/AdminDashboard', () => ({
    AdminDashboard: vi.fn(() => null),
}));

import { authExport } from '@/actions/auth-export';
import { getProgress } from '@/actions/getProgress';
import { updatePlayerRecords } from '@/actions/updatePlayerRecords';
import AdminPage from '@/app/footy/admin/page';
import { AdminDashboard } from '@/components/AdminDashboard/AdminDashboard';

describe('Admin Dashboard page', () => {
    it('renders the AdminDashboard component', () => {
        AdminPage();

        expect(AdminDashboard).toHaveBeenCalledTimes(1);
    });

    it('passes the updatePlayerRecords and getProgress server actions to AdminDashboard', () => {
        AdminPage();

        const [props] = (AdminDashboard as Mock).mock.calls[0] as [
            { onUpdatePlayerRecords: unknown; getProgress: unknown },
        ];
        expect(props.onUpdatePlayerRecords).toBe(updatePlayerRecords);
        expect(props.getProgress).toBe(getProgress);
    });

    it('passes the authExport server action to AdminDashboard', () => {
        AdminPage();

        const [props] = (AdminDashboard as Mock).mock.calls[0] as [
            { onExportAuth: unknown },
        ];
        expect(props.onExportAuth).toBe(authExport);
    });
});

import type { Mock } from 'vitest';
import { beforeEach, describe, expect, it, vi } from 'vitest';

vi.mock('services/GameDay');

vi.mock('next/navigation', () => ({
    notFound: vi.fn(() => {
        throw new Error('not_found');
    }),
    permanentRedirect: vi.fn(() => {
        throw new Error('permanent_redirect');
    }),
}));

vi.mock('react', async () => {
    const actual = await vi.importActual<typeof import('react')>('react');
    return { ...actual, cache: (fn: unknown) => fn };
});

vi.mock('@/components/YearPageShell/YearPageShell', () => ({
    YearPageShell: vi.fn(() => null),
}));

import GamesPage, { generateMetadata } from '@/app/footy/games/page';
import { YearPageShell } from '@/components/YearPageShell/YearPageShell';
import gameDayService from '@/services/GameDay';

describe('Games page', () => {
    beforeEach(() => {
        vi.clearAllMocks();
        (gameDayService.getAllYears as Mock).mockResolvedValue([0, 2023, 2024]);
        (gameDayService.getCurrent as Mock).mockResolvedValue({ id: 1249 });
        (gameDayService.getGamesPlayed as Mock).mockResolvedValue(5);
        (gameDayService.getGamesCancelled as Mock).mockResolvedValue(1);
        (gameDayService.getGamesRemaining as Mock).mockResolvedValue(3);
        (gameDayService.getAll as Mock).mockResolvedValue([]);
    });

    it('fetches the count of games played and games remaining', async () => {
        await GamesPage({ searchParams: Promise.resolve({ year: '2024' }) });

        expect(gameDayService.getGamesPlayed).toHaveBeenCalledWith(2024, 1249);
        expect(gameDayService.getGamesRemaining).toHaveBeenCalledWith(2024);
    });

    it('fetches both counts in parallel via Promise.all', async () => {
        const callOrder: string[] = [];
        (gameDayService.getGamesPlayed as Mock).mockImplementation(() => {
            callOrder.push('played-start');
            return 5;
        });
        (gameDayService.getGamesCancelled as Mock).mockImplementation(() => {
            callOrder.push('cancelled-start');
            return 1;
        });
        (gameDayService.getGamesRemaining as Mock).mockImplementation(() => {
            callOrder.push('remaining-start');
            return 3;
        });

        await GamesPage({ searchParams: Promise.resolve({ year: '2024' }) });

        expect(callOrder.sort()).toEqual([
            'cancelled-start',
            'played-start',
            'remaining-start',
        ]);
        expect(gameDayService.getGamesPlayed).toHaveBeenCalledTimes(1);
        expect(gameDayService.getGamesCancelled).toHaveBeenCalledTimes(1);
        expect(gameDayService.getGamesRemaining).toHaveBeenCalledTimes(1);
    });

    it('passes the played/cancelled/confirmed subhead to YearPageShell', async () => {
        await GamesPage({ searchParams: Promise.resolve({ year: '2024' }) });

        const [props] = (YearPageShell as Mock).mock.calls[0] as [
            { subheading: unknown },
        ];
        expect(props.subheading).toBe('5 played, 1 cancelled, 3 confirmed');
    });

    it('handles service errors gracefully', async () => {
        (gameDayService.getGamesPlayed as Mock).mockRejectedValue(
            new Error('DB failed'),
        );

        await expect(
            GamesPage({ searchParams: Promise.resolve({ year: '2024' }) }),
        ).rejects.toThrow('DB failed');
    });

    it('calls notFound when the selected year is not in allYears', async () => {
        await expect(
            GamesPage({ searchParams: Promise.resolve({ year: '1999' }) }),
        ).rejects.toThrow('not_found');
    });

    it('calls notFound when the year param is not a valid integer', async () => {
        await expect(
            GamesPage({
                searchParams: Promise.resolve({ year: 'notanumber' }),
            }),
        ).rejects.toThrow('not_found');
    });

    it('redirects to the canonical URL when the current URL does not match', async () => {
        await expect(
            GamesPage({ searchParams: Promise.resolve({}) }),
        ).rejects.toThrow('permanent_redirect');
    });

    it('does not redirect when year=2024 is already the canonical URL', async () => {
        await expect(
            GamesPage({ searchParams: Promise.resolve({ year: '2024' }) }),
        ).resolves.toBeDefined();
    });

    it('generates metadata with the year-specific title', async () => {
        const metadata = await generateMetadata({
            searchParams: Promise.resolve({ year: '2024' }),
        });

        expect(metadata.title).toBe('2024 Games');
    });

    it('does not redirect when year=0 is already explicit in the query', async () => {
        await expect(
            GamesPage({ searchParams: Promise.resolve({ year: '0' }) }),
        ).resolves.toBeDefined();
    });

    it('omits played/cancelled/confirmed counts from the subhead when they are zero', async () => {
        (gameDayService.getGamesPlayed as Mock).mockResolvedValue(0);
        (gameDayService.getGamesCancelled as Mock).mockResolvedValue(0);
        (gameDayService.getGamesRemaining as Mock).mockResolvedValue(0);

        await GamesPage({ searchParams: Promise.resolve({ year: '2024' }) });

        const [props] = (YearPageShell as Mock).mock.calls[0] as [
            { subheading: unknown },
        ];
        expect(props.subheading).toBe('');
    });
});

import { PlayerResponse } from 'prisma/generated/enums';
import { renderToStaticMarkup } from 'react-dom/server';
import type { Mock } from 'vitest';
import { beforeEach, describe, expect, it, vi } from 'vitest';

import type { GameInvitationResponseDetails } from '@/types/GameInvitationResponseDetails';

vi.mock('@/actions/submitGameInvitationResponse', () => ({
    submitGameInvitationResponse: vi.fn(),
}));

vi.mock('@/components/StatusNotification/StatusNotification', () => ({
    StatusNotification: vi.fn(() => null),
}));

vi.mock(
    '@/components/GameInvitationResponseForm/GameInvitationResponseForm',
    () => ({
        GameInvitationResponseForm: vi.fn(() => null),
    }),
);

vi.mock('@/lib/gameInvitations', () => ({
    getGameInvitationResponseDetails: vi.fn(),
}));

import Page from '@/app/footy/response/[token]/page';
import { GameInvitationResponseForm } from '@/components/GameInvitationResponseForm/GameInvitationResponseForm';
import { StatusNotification } from '@/components/StatusNotification/StatusNotification';
import { getGameInvitationResponseDetails } from '@/lib/gameInvitations';

const sampleDetails = {
    token: 'fresh-token',
    playerId: 7,
    playerName: 'Alice Example',
    playerLogin: 'alice-example',
    gameDayId: 42,
    response: PlayerResponse.Yes,
    goalie: true,
    comment: 'Looking forward to it',
};

describe('Game Invitation Response page', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('fetches the invitation details for the token', async () => {
        (getGameInvitationResponseDetails as Mock).mockResolvedValue(
            sampleDetails,
        );

        const element = await Page({
            params: Promise.resolve({ token: sampleDetails.token }),
        });

        renderToStaticMarkup(element);

        expect(getGameInvitationResponseDetails).toHaveBeenCalledWith(
            sampleDetails.token,
        );
        const [[props]] = (GameInvitationResponseForm as Mock).mock.calls as [
            { details: GameInvitationResponseDetails },
        ][];
        expect(props.details).toEqual(sampleDetails);
    });

    it('renders a missing-details message when the invitation cannot be found', async () => {
        (getGameInvitationResponseDetails as Mock).mockResolvedValue(null);

        await Page({
            params: Promise.resolve({ token: 'missing-token' }),
        });

        const [props] = (StatusNotification as Mock).mock.calls[0] as [
            { variant: unknown; message: unknown; anchor: unknown },
        ];
        expect(props.variant).toBe('plain');
        expect(props.message).toBe('Invitation details are missing.');
        expect(props.anchor).toEqual({
            href: '/footy/game',
            label: 'Go to the game page',
        });
    });
});

