1	import { MantineProvider } from '@mantine/core';
2	import { screen } from '@testing-library/react';
3	import type { useRouter } from 'next/navigation';
4	import { ReactNode } from 'react';
5	import { vi } from 'vitest';
6	
7	import { theme } from '@/theme';
8	
9	/** The App Router instance returned by `useRouter`. */
10	type AppRouter = ReturnType<typeof useRouter>;
11	
12	interface WrapperProps {
13	    children?: ReactNode;
14	}
15	
16	/**
17	 * In-memory colour scheme manager for tests to avoid touching runtime
18	 * localStorage and triggering Node experimental warnings.
19	 */
20	const testColorSchemeManager = {
21	    get: (defaultValue: 'auto' | 'dark' | 'light') => defaultValue,
22	    set: () => undefined,
23	    subscribe: () => undefined,
24	    unsubscribe: () => undefined,
25	    clear: () => undefined,
26	};
27	
28	/**
29	 * Test wrapper component that provides Mantine theming context.
30	 * Wraps children with MantineProvider configured for light color scheme,
31	 * using the app's actual theme (`@/theme`) so tests see the same
32	 * `theme.other.*` tokens and component defaults as production, rather than
33	 * Mantine's bare default theme.
34	 *
35	 * @param props - The component props
36	 * @param props.children - React nodes to be wrapped with Mantine provider
37	 * @returns A React component with Mantine provider context
38	 */
39	export const Wrapper = ({ children }: WrapperProps) => {
40	    return (
41	        <MantineProvider
42	            theme={theme}
43	            colorSchemeManager={testColorSchemeManager}
44	            defaultColorScheme="light"
45	        >
46	            {children}
47	        </MantineProvider>
48	    );
49	};
50	
51	/**
52	 * Builds a complete mock App Router for `vi.mocked(useRouter).mockReturnValue`.
53	 * Every method is a fresh `vi.fn()` so tests only need to name the ones they
54	 * assert on. Centralising the shape here means a Next.js release that adds a
55	 * member to the router interface is a one-line fix rather than an edit to every
56	 * spec that mocks it.
57	 *
58	 * @param overrides - Router members to replace, typically the spy under test.
59	 * @returns A router object satisfying the full `useRouter` return type.
60	 *
61	 * @example
62	 * const push = vi.fn();
63	 * vi.mocked(useRouter).mockReturnValue(mockRouter({ push }));
64	 */
65	export const mockRouter = (overrides: Partial<AppRouter> = {}): AppRouter => ({
66	    push: vi.fn(),
67	    replace: vi.fn(),
68	    back: vi.fn(),
69	    forward: vi.fn(),
70	    refresh: vi.fn(),
71	    prefetch: vi.fn(),
72	    bfcacheId: '',
73	    ...overrides,
74	});
75	
76	/**
77	 * Extracts and parses props from a rendered element's text content. Each
78	 * standard mock is expected to render a single element whose text looks like:
79	 * `<div>{id}: {JSON.stringify(props)}</div>`, for example:
80	 * `<div>MyComponent: {"prop1":"value1"}</div>`.
81	 *
82	 * This deliberately uses loose JSON parsing rather than zod schema validation
83	 * to keep tests simple and focused on rendering behavior.
84	 *
85	 * @template T - The type of the props object to be returned.
86	 * @param id - The identifier prefix used to locate the element. The function
87	 * looks for text starting with `${id}:` and parses the JSON that follows.
88	 * @returns The parsed props object(s) of type T.
89	 * @throws Will fail test assertions if the element is not found or if the JSON
90	 * is invalid.
91	 *
92	 * @example
93	 * // For `<div>MyComponent: {"prop1":"value1"}</div>`:
94	 * const [props] = extractMockProps<MyComponentProps>('MyComponent');
95	 */
96	export const extractMockProps = <T,>(id: string) => {
97	    const mockElements = screen.getAllByText(new RegExp(`^${id}:`));
98	    const result: T[] = [];
99	    for (const element of mockElements) {
100	        const json = element.textContent?.replace(
101	            new RegExp(`^${id}:\\s*`),
102	            '',
103	        );
104	        expect(typeof json).toBe('string');
105	        expect(json.trim()).not.toBe('');
106	        result.push(JSON.parse(json) as T);
107	    }
108	    expect(result.length).toBeGreaterThan(0);
109	    return result;
110	};
